# Pudding Sword Cursor -- install
# Generated by cursor-studio cursorgen -- edit the theme, not this file.
#
# Everything stays inside your user profile:
#   files    : %LOCALAPPDATA%\Cursors\Pudding Sword Cursor
#   registry : HKCU\Control Panel\Cursors (+ the Schemes sub-key)
# Administrator rights are NOT required.
#
# Use -DryRun to see what would happen without changing anything.

param([switch]$DryRun)

$ErrorActionPreference = 'Stop'

$ThemeName   = 'Pudding Sword Cursor'
$SourceDir   = $PSScriptRoot
$CursorsKey  = 'HKCU:\Control Panel\Cursors'
$SchemesKey  = 'HKCU:\Control Panel\Cursors\Schemes'
$BackupPath  = Join-Path $SourceDir 'uninstall-backup.json'
$TargetDir   = Join-Path $env:LOCALAPPDATA ('Cursors\' + $ThemeName)

# slot order == the order Windows expects in the scheme string
$Slots = [ordered]@{
    'Arrow'        = '01 Arrow.ani'
    'Help'         = '02 Help.ani'
    'AppStarting'  = '03 AppStarting.ani'
    'Wait'         = '04 Wait.ani'
    'Crosshair'    = '05 Crosshair.ani'
    'IBeam'        = '06 IBeam.ani'
    'NWPen'        = '07 NWPen.ani'
    'No'           = '08 No.ani'
    'SizeNS'       = '09 SizeNS.ani'
    'SizeWE'       = '10 SizeWE.ani'
    'SizeNWSE'     = '11 SizeNWSE.ani'
    'SizeNESW'     = '12 SizeNESW.ani'
    'SizeAll'      = '13 SizeAll.ani'
    'UpArrow'      = '14 UpArrow.ani'
    'Hand'         = '15 Hand.ani'
}

function Update-Cursors {
    if ($DryRun) {
        Write-Host '  [dry-run] would call SystemParametersInfo(SPI_SETCURSORS)'
        return
    }
    # SPI_SETCURSORS = 0x0057, SPIF_UPDATEINIFILE | SPIF_SENDCHANGE = 0x0003
    if (-not ('CursorTheme.Native' -as [type])) {
        Add-Type -Namespace CursorTheme -Name Native -MemberDefinition @'
[DllImport("user32.dll", SetLastError = true)]
public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, System.IntPtr pvParam, uint fWinIni);
'@
    }
    [void][CursorTheme.Native]::SystemParametersInfo(0x0057, 0, [IntPtr]::Zero, 0x0003)
}

function Get-CursorValue([string]$Name) {
    try {
        $item = Get-ItemProperty -Path $CursorsKey -Name $Name -ErrorAction Stop
    } catch {
        return $null
    }
    if ($null -eq $item) { return $null }
    return [string]$item.$Name
}

function Set-CursorValue([string]$Name, [string]$Value) {
    if ($DryRun) {
        Write-Host ("  [dry-run] HKCU\\Control Panel\\Cursors\\" + $Name + " = " + $Value)
        return
    }
    Set-ItemProperty -Path $CursorsKey -Name $Name -Value $Value -Type String
}

Write-Host ''
Write-Host ("Installing '" + $ThemeName + "' ...") -ForegroundColor Cyan
if ($DryRun) { Write-Host '  (dry run: nothing will be changed)' }

# ---- 1. copy the cursor files ------------------------------------------------
if (-not $DryRun -and -not (Test-Path -LiteralPath $TargetDir)) {
    New-Item -ItemType Directory -Force -Path $TargetDir | Out-Null
}
$copied = 0
foreach ($file in $Slots.Values) {
    $source = Join-Path $SourceDir $file
    if (-not (Test-Path -LiteralPath $source)) {
        throw "Cursor file is missing from the theme folder: $file"
    }
    $destination = Join-Path $TargetDir $file
    if ($DryRun) {
        Write-Host ("  [dry-run] copy " + $file + " -> " + $destination)
    } elseif ([System.IO.Path]::GetFullPath($source) -ne [System.IO.Path]::GetFullPath($destination)) {
        Copy-Item -LiteralPath $source -Destination $destination -Force
    }
    $copied++
}
Write-Host ("  {0} cursor files -> {1}" -f $copied, $TargetDir)

# ---- 2. back up the current settings (first install only) -------------------
if (Test-Path -LiteralPath $BackupPath) {
    Write-Host '  keeping the existing uninstall-backup.json (run uninstall first to re-capture)'
} elseif ($DryRun) {
    Write-Host '  [dry-run] would save the current cursor settings to uninstall-backup.json'
} else {
    $backup = [ordered]@{
        theme   = $ThemeName
        created = (Get-Date).ToString('s')
        values  = [ordered]@{}
    }
    foreach ($role in $Slots.Keys) {
        $backup.values[$role] = Get-CursorValue $role
    }
    $backup.values['Scheme'] = Get-CursorValue 'Scheme'
    $backup.values['SchemeSource'] = Get-CursorValue 'Scheme Source'
    $backup | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $BackupPath -Encoding UTF8
    Write-Host '  previous cursor settings saved to uninstall-backup.json'
}

# ---- 3. registry: the 15 role values, in slot order ------------------------
foreach ($role in $Slots.Keys) {
    Set-CursorValue $role (Join-Path $TargetDir $Slots[$role])
}
Write-Host ("  {0} cursor roles registered (Arrow ... Hand)" -f $Slots.Count)

# ---- 4. registry: the scheme entry (same order, comma separated) -----------
if (-not $DryRun -and -not (Test-Path -LiteralPath $SchemesKey)) {
    New-Item -Path $SchemesKey -Force | Out-Null
}
$schemeValue = (@($Slots.Keys | ForEach-Object { Join-Path $TargetDir $Slots[$_] })) -join ','
if ($DryRun) {
    Write-Host ("  [dry-run] scheme '" + $ThemeName + "' = " + $schemeValue)
} else {
    Set-ItemProperty -Path $SchemesKey -Name $ThemeName -Value $schemeValue -Type String
    Set-ItemProperty -Path $CursorsKey -Name 'Scheme' -Value $ThemeName -Type String
}
Write-Host ("  scheme '" + $ThemeName + "' registered")

# ---- 5. apply immediately ---------------------------------------------------
Update-Cursors

Write-Host ''
if ($DryRun) {
    Write-Host 'Dry run finished: nothing was changed.' -ForegroundColor Yellow
} else {
    Write-Host ("Done. '" + $ThemeName + "' is active.") -ForegroundColor Green
    Write-Host '  If the pointer does not change right away, open'
    Write-Host '  Settings > Mouse > Additional mouse settings > Pointers and pick'
    Write-Host ("  '" + $ThemeName + "', or sign out and back in.")
    Write-Host '  To undo: run uninstall.bat.'
}
